// Accepts { channel, channel_user_id, message, name, location_area } plus an
// optional binary attachment (a payment receipt photo/PDF). Adapt for a raw
// WhatsApp Business webhook payload if wiring that directly.
const item = $input.first();
const b = item.json.body || item.json || {};
const binary = item.binary || {};
const attachmentKey = Object.keys(binary)[0] || null;

const channel = (b.channel || 'website').toLowerCase();
const channelUserId = String(b.channel_user_id || b.session_id || 'anon').trim();
const message = String(b.message || '').trim();
const name = b.name ? String(b.name).trim() : null;
const locationArea = b.location_area ? String(b.location_area).trim() : null;

if (!message && !attachmentKey) {
  return [{ json: { error: true, message: 'No message or attachment provided.' } }];
}

return [{
  json: { error: false, channel, channel_user_id: channelUserId, message_text: message,
           name, location_area: locationArea, has_attachment: !!attachmentKey, attachment_key: attachmentKey },
  binary
}];

const ctx = $input.first().json;
const sinhala = /[\u0D80-\u0DFF]/;
const tamil = /[\u0B80-\u0BFF]/;
let detected = null;
if (sinhala.test(ctx.message_text)) detected = 'sinhala';
else if (tamil.test(ctx.message_text)) detected = 'tamil';
return [{ json: { ...ctx, detected_language: detected } }];

// Prefer an explicit reference typed by the student (e.g. ALA-ENR-20260806-0001);
// fall back to their most recent pending enrollment.
const msg = $('Detect Language').first().json.message_text || '';
const explicit = msg.match(/ALA-ENR-\d{8}-\d{4}/i);
const found = $input.first().json;

const enrollmentNumber = explicit ? explicit[0].toUpperCase()
  : (found && found.found ? found.enrollment_number : null);

if (!enrollmentNumber) {
  return [{ json: { no_enrollment: true } }];
}
return [{ json: { enrollment_number: enrollmentNumber,
  receipt_url: $('Upload Receipt to Storage').first().json.Key
    ? `https://cxmiayrfokrugicqpzxi.supabase.co/storage/v1/object/public/payment-receipts/${$('Upload Receipt to Storage').first().json.Key.split('/').pop()}`
    : null } }];

